parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": [
        "CONSULTA_TECNICA",
        "COMUNICACION_AL_CLIENTE",
        "DERIVAR_AL_TALLER",
        "OTRO"
      ]
    },
    "motivo": {
      "type": "string"
    },
    "confianza": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "datos_conocidos": {
      "type": "string",
      "description": "Una línea con los datos que el cliente ya dio en la conversación; n/d si ninguno"
    }
  },
  "required": [
    "categoria",
    "motivo",
    "confianza",
    "datos_conocidos"
  ]
}

