parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "asunto_principal": {
      "type": "string",
      "description": "Problema o pedido central del cliente, en una frase"
    },
    "puntos_clave": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "2 a 5 hechos accionables"
    },
    "accion_requerida": {
      "type": "string",
      "description": "Próxima acción concreta del taller, en una frase"
    }
  },
  "required": [
    "asunto_principal",
    "puntos_clave",
    "accion_requerida"
  ],
  "additionalProperties": false
}
